"""Complete 24 original cancer diagnosis, staging and evidence-interpretation questions."""
from create_oncology_diagnosis import rows,q,NC,GR,EC,ref
from qbank_authoring import finalize
TM=ref('NCI tumor-marker facts','https://www.cancer.gov/about-cancer/diagnosis-staging/diagnosis/tumor-markers-fact-sheet')
LB=ref('ASCO ctDNA testing guideline: 2026','https://doi.org/10.1200/OP-26-00311')
RC=ref('RECIST working group: RECIST 1.1','https://recist.eortc.org/recist-1-1/')
SC=ref('NCI cancer screening evidence overview','https://www.cancer.gov/about-cancer/screening/hp-screening-overview-pdq')

q('A patient with ascites and no tissue diagnosis has a raised CA-125. Which interpretation is correct?', 'CA-125 can rise in malignant and benign serosal/inflammatory conditions and is not diagnostic of ovarian cancer alone',[
 ('The concentration alone establishes the primary site','Specificity is insufficient.'),('A normal result would exclude all ovarian cancer','Sensitivity is incomplete.'),('Every raised tumor marker is suitable for general-population screening','Screening requires evidence beyond an association.')],
 'A tumor-associated marker need not be tumor-specific','**Clinical context and validated use determine meaning.**',['Markers can help monitor known disease or select treatment in defined settings.','Benign disease and physiological factors can produce abnormal values.'],'**Investigate the syndrome rather than treating the marker as histology.**',['Use imaging and tissue/fluid assessment as indicated.','Avoid indiscriminate panels that create false certainty.'],[['Marker rise','Not uniquely malignant'],['Diagnosis','Requires context'],['Screening','Separate evidence standard']],[TM],style='clinical_scenario')

q('A cirrhotic patient has a suspicious liver lesion but normal AFP. Which conclusion is appropriate?', 'Normal AFP does not exclude hepatocellular carcinoma',[
 ('HCC requires a high AFP in every case','Some HCCs do not produce a diagnostic AFP rise.'),('The lesion must be a metastasis because AFP is normal','AFP alone does not settle the differential.'),('AFP replaces all imaging-based assessment','Validated liver imaging criteria and context are central.')],
 'A negative marker is not a universal cancer exclusion test','**AFP has imperfect sensitivity and specificity.**',['Selected high-risk patients can be diagnosed using validated characteristic imaging criteria.','Atypical lesions may require further assessment or biopsy.'],'**Follow a liver-lesion diagnostic pathway.**',['Do not dismiss a suspicious lesion from one blood test.','Assess liver reserve and tumor extent separately.'],[['AFP normal','HCC still possible'],['Imaging','Key diagnostic role'],['Context','Risk population and lesion pattern']],[TM,ref('AASLD HCC practice guidance','https://pmc.ncbi.nlm.nih.gov/articles/PMC10663390/')],style='clinical_scenario')

q('A plasma ctDNA assay finds no actionable alteration in metastatic cancer. Which statement is most appropriate?', 'A negative plasma result may reflect limited shedding or assay sensitivity; seek tissue testing when indicated and feasible',[
 ('No actionable tumor alteration can exist','A noninformative plasma result is not a complete genomic exclusion.'),('The patient therefore does not have cancer','The test is not a universal diagnostic rule-out.'),('Every negative result should be repeated indefinitely without considering tissue','The next step depends on the clinical question and available material.')],
 'Absence of a plasma signal may be biological or technical','**Tumor fraction, disease distribution and assay coverage affect detection.**',['Fusions and copy-number events can have additional assay limitations.','Positive results also require clinical validity and context.'],'**Use a disease-specific biomarker strategy.**',['Do not delay effective care while chasing an uninformative test.','Discuss discordant results with pathology/molecular experts.'],[['Plasma negative','Not necessarily tumor negative'],['Limitations','Shedding/coverage/sensitivity'],['Next step','Appropriate tissue confirmation']],[LB],style='clinical_scenario')

q('A tumor-only assay detects a pathogenic BRCA variant. Which conclusion is correct?', 'The result may be somatic or germline; appropriate germline evaluation is needed to determine inherited status',[
 ('Every tumor BRCA variant is inherited','Tumors can acquire somatic variants.'),('Tumor-only testing excludes an inherited variant','It does not establish that either.'),('Family testing should proceed as though germline status is already confirmed','Inherited-risk counseling requires proper confirmation.')],
 'The tested compartment determines the inference','**Tumor sequencing answers a different question from constitutional testing.**',['A potentially inherited result can have implications for the patient and relatives.','Consent and counseling are important.'],'**Refer for indicated genetics assessment and confirmatory testing.**',['Do not use a variant of uncertain significance as a pathogenic finding.','Integrate treatment and hereditary-risk decisions appropriately.'],[['Tumor-only','Somatic or germline possible'],['Germline test','Inherited status'],['Family care','After appropriate interpretation']],[ref('NCI genetic testing for inherited cancer susceptibility','https://www.cancer.gov/about-cancer/causes-prevention/genetics/genetic-testing-fact-sheet')])

q('What distinguishes a predictive biomarker from a purely prognostic biomarker?', 'A predictive biomarker informs differential benefit or harm from a particular treatment',[
 ('It only describes outcome regardless of treatment','That is a prognostic role.'),('It must always be a serum protein','Predictive markers can be genomic, tissue-based or other validated measures.'),('It is automatically useful without evidence linking it to treatment response','Clinical validation is required.')],
 'Outcome association and treatment interaction are different claims','**A marker can be both prognostic and predictive, but one role does not prove the other.**',['An actionable alteration requires evidence in the relevant tumor/therapy context.','Assay quality and cutoff matter.'],'**Use validated disease-specific evidence.**',['Do not treat every mutation as a drug target.','Consider resistance alterations and coexisting factors.'],[['Prognostic','Outcome association'],['Predictive','Treatment-effect information'],['Validation','Clinical context and assay']],[TM])

q('A trial improves progression-free survival but has not shown an overall-survival difference. Which interpretation is most accurate?', 'Delay in progression is demonstrated, but an overall-survival benefit has not been established by that result alone',[
 ('PFS improvement mathematically guarantees longer survival','Subsequent treatment, toxicity and other factors can separate endpoints.'),('The result proves the treatment has no clinical value','Symptom control and time without progression may matter, depending on magnitude and harms.'),('Overall survival measures only radiographic tumor shrinkage','OS concerns time to death, not imaging response.')],
 'Read the endpoint actually tested','**PFS and OS answer related but different questions.**',['Quality of life, toxicity, crossover and follow-up affect interpretation.','A surrogate relationship is disease- and context-dependent.'],'**Judge the total patient-important benefit-risk profile.**',['Avoid replacing an unproven endpoint with a stronger claim.','Review absolute effects and confidence intervals.'],[['PFS','Progression/death endpoint'],['OS','Death endpoint'],['Decision','Magnitude, symptoms and harms']],[ref('FDA oncology clinical-trial endpoint guidance','https://www.fda.gov/regulatory-information/search-fda-guidance-documents/clinical-trial-endpoints-approval-cancer-drugs-and-biologics')])

q('Screening moves diagnosis 3 years earlier, but patients die at the same age as before. Apparent survival from diagnosis improves. Which bias is illustrated?', 'Lead-time bias',[
 ('Length bias','This concerns preferential detection of slower-growing disease.'),('A proven mortality reduction','The death timing has not changed.'),('Stage migration','This concerns reclassification between stages.')],
 'Starting the survival clock earlier can create apparent benefit','**Longer survival after diagnosis need not mean a longer life.**',['Mortality and appropriate randomized comparisons are important screening outcomes.','Quality of life and harms also matter.'],'**Do not infer screening efficacy from diagnosis-to-death survival alone.**',['Consider overdiagnosis and treatment burden.','Use population-level evidence appropriate to the screening strategy.'],[['Diagnosis','Earlier'],['Death','Unchanged'],['Apparent benefit','Longer measured survival']],[SC])

q('A screening program detects a disproportionate number of slow-growing cancers because they remain detectable for longer. Which bias is described?', 'Length bias',[
 ('Lead-time bias alone','Earlier clock start is a different mechanism.'),('Random measurement error','The selection is systematically related to disease natural history.'),('A guarantee that all detected cancers needed treatment','Some may represent overdiagnosis.')],
 'The screen samples time spent in a detectable state','**Indolent disease can be overrepresented among screen-detected cases.**',['Aggressive interval cancers may be underrepresented.','Better observed survival can reflect this selection.'],'**Use appropriate trial outcomes to assess benefit.**',['Do not compare screened and symptomatic cohorts naively.','Consider harms and the risk of detecting nonthreatening disease.'],[['Slow disease','Longer detectable window'],['Aggressive disease','May present between screens'],['Bias','Favorable case mix']],[SC])

q('What does overdiagnosis in cancer screening mean?', 'Detection of a cancer that would not have caused symptoms or death during that person’s lifetime',[
 ('A false-positive test in someone with no cancer','Overdiagnosis can involve a real pathological cancer.'),('Any diagnosis made before symptoms','Many early diagnoses are beneficial; the natural history matters.'),('A pathology laboratory naming the wrong tumor','That is misdiagnosis, a different problem.')],
 'A true diagnosis can still create net harm','**Overdiagnosis can lead to unnecessary treatment and anxiety.**',['It differs from false positives and lead-time effects.','The proportion varies by cancer, population and screening method.'],'**Balance screening benefits against downstream harms.**',['Use risk-adapted management where evidence supports it.','Do not assume every detected lesion requires the same immediate treatment.'],[['False positive','No cancer'],['Overdiagnosis','Real cancer that would not threaten lifetime health'],['Consequence','Potential overtreatment']],[SC])

q('More sensitive staging moves a group with small metastases from a lower stage to a higher stage, making outcomes appear better in both stage groups without changing any patient outcome. Which phenomenon is illustrated?', 'Stage migration or the Will Rogers phenomenon',[
 ('A proven treatment-related survival improvement','No individual outcome changed in the example.'),('Lead-time bias as the only mechanism','The key change is group assignment, not simply earlier diagnosis.'),('A change in tumor grade','This example concerns extent-based classification.')],
 'Group composition can change a stage-specific statistic','**Improved detection can reclassify patients between prognostic groups.**',['Cross-era stage-specific comparisons can therefore mislead.','Overall outcomes and consistent classification need review.'],'**Consider staging methods when interpreting historical comparisons.**',['Do not attribute every apparent stage-specific gain to treatment.','Use comparable populations and methods.'],[['Change','More sensitive staging'],['Effect','Different group composition'],['Limit','Apparent improvement without individual benefit']],[NC,SC])

q('Under RECIST 1.1, target-lesion sum falls from 100 mm at baseline to 68 mm, with no new lesions or other progression. Which target-lesion response is met?', 'Partial response',[
 ('Complete response','Residual measurable disease remains.'),('Stable disease','The thirty-two-percent decrease meets the partial-response threshold.'),('Progressive disease','The target burden has decreased and no other progression is described.')],
 'Use the specified reference and measurement rule','**A decrease of at least thirty percent from baseline supports target-lesion partial response.**',['Full response assessment also considers nontarget disease and new lesions.','Progression uses a different reference, generally the smallest prior sum, with relative and absolute requirements.'],'**Apply the complete protocol consistently.**',['Do not substitute an isolated percentage for the whole assessment.','Use the same valid imaging and lesion-selection rules.'],[['Baseline','100 mm'],['Current','68 mm'],['Change','32% decrease']],[RC],style='clinical_scenario')

q('A clinically stable patient on immunotherapy has an initial scan suggesting progression. What is the appropriate iRECIST principle in a suitable trial/protocol context?', 'Initial unconfirmed progression may require scheduled confirmation, while clinical deterioration still demands prompt reassessment',[
 ('All progression on immunotherapy is pseudoprogression','True progression is common and must not be dismissed.'),('Every patient must continue treatment regardless of worsening condition','Clinical safety and the treatment protocol matter.'),('iRECIST proves improved survival from treatment beyond progression','It standardizes assessment rather than proving benefit.')],
 'Unusual response patterns require controlled interpretation','**iRECIST distinguishes unconfirmed from confirmed immune-related progression.**',['It was designed as a standardized research response framework.','Continuation decisions require clinical stability and appropriate safeguards.'],'**Do not use pseudoprogression as an automatic explanation.**',['Assess symptoms, organ threats and alternative causes.','Use the predefined reassessment interval and management plan.'],[['Initial change','Possible iUPD'],['Confirmation','Protocol-based'],['Clinical worsening','Urgent reassessment']],[ref('RECIST working group: iRECIST','https://recist.eortc.org/irecist/')],style='clinical_scenario')

if __name__=='__main__':finalize('Oncology',1,'Principles of Cancer Diagnosis and Staging','onco-principles',rows,24)
